{
    audio: "xinfu_dianhua",
    trigger: { player: ["phaseZhunbeiBegin", "phaseJieshuBegin"] },
    frequent: true,
    async content(event, trigger, player) {
      const cards2 = get.cards(4, true);
      await game.cardsGotoOrdering(cards2);
      const result = await player.chooseToMove(true).set("list", [["牌堆顶", cards2], ["获得"]]).set("prompt", "点化：获得一张已记录花色的牌，将其余牌以任意顺序放回牌堆顶").set("filterx", (card, player2) => player2.getStorage("x_dc_falu").includes(get.suit(card))).set("filterOk", (moved) => {
        const { filterx: filter, player: player2 } = get.event();
        return moved[1].length === 1 || moved[0].every((card) => !filter(card, player2));
      }).set("filterMove", (from, to, moved) => {
        const { filterx: filter, player: player2 } = get.event();
        if (moved[0].includes(from.link)) {
          if (typeof to === "number") {
            return to === 0 || !moved[1].length && filter(from.link, player2);
          }
          return moved[0].includes(to.link) || filter(from.link, player2);
        }
        if (typeof to === "number") {
          return to === 0;
        }
        return filter(to.link, player2);
      }).set("processAI", (list) => {
        const { filterx: filter, player: player2 } = get.event();
        const cards3 = list[0][1].slice(0).filter((card) => filter(card, player2));
        if (cards3?.length) {
          const card = cards3.maxBy((card2) => get.value(card2, player2));
          return [list[0][1].remove(card), [card]];
        }
        return [list[0][1], []];
      }).forResult();
      if (result.bool && result.moved) {
        const top = result.moved[0].reverse();
        const gains = result.moved[1];
        if (top?.length) {
          await game.cardsGotoPile(top, "insert");
        }
        if (gains?.length) {
          await player.gain(gains, "gain2");
        }
      }
    }
  }

