          target3.line(player2);
          if (player2 !== target3 && (get.mode() !== "identity" || target3.identity !== "nei")) {
            target3.addExpose(0.15);
          }
          await player2.draw();
        }
      }
      const result = await player2.chooseTarget("是否对一名手牌数等于自己的目标角色造成1点伤害？", (card2, player3, target3) => {
        return get.event().getParent().targets.includes(target3) && target3.countCards("h") == player3.countCards("h");
      }).set("ai", (target3) => {
        const player3 = get.player();
        return get.damageEffect(target3, player3, player3);
      }).forResult();
      if (!result?.targets?.length) {
        return;
      }
      const [target2] = result.targets;
      player2.line(target2, "green");
      if (get.mode() !== "identity" || player2.identity !== "nei") {
        player2.addExpose(0.15);
