          val /= 2;
        } else {
          val /= 4;
        }
        if (attitude == 0 || result == 0) {
          return 0;
        }
        if (attitude > 0) {
          return result - val;
        }
        return -result - val;
      }).set("judging", trigger.player.judging[0]).setHiddenSkill(event.skill).forResult();
    },
