sp:wylianji.code:
{
    enable: "phaseUse",
    audio: 2,
    usable: 1,
    filter(event2, player2) {
      return player2.hasCard(lib.skill.wylianji.filterCard);
    },
    check(card2) {
      if (card2.name == "sha") {
        return 1;
      } else {
        if (get.tag(card2, "damage")) {
          if (get.tag(card2, "multineg")) {
            return 5;
          }
          return 2;
        }
      }
      return 0;
    },
    filterCard(card2) {
      return get.name(card2) == "sha" || get.type(card2, "trick") == "trick" && get.color(card2) == "black" && !get.info(card2).multitarget && get.info(card2).enable;
    },
    filterTarget(card2, player2, target2) {
      return target2 != player2 && !target2.isMin() && (player2.canUse(card2, target2, false) || game.hasPlayer(function(current) {
        return current != player2 && target2.canUse(card2, current);
      }));
    },
    discard: false,
    lose: true,
    delay: false,
    async content(event2, trigger2, player2) {
      const { target: target2, cards: cards2 } = event2;
      await player2.showCards(get.translation(player2) + "对" + get.translation(target2) + "发动了【连计】", cards2);
      let equip1 = get.cardPile2(function(card3) {
        return get.subtype(card3) == "equip1";
      }, "random");
      if (!equip1) {
        player2.popup("杯具");
        game.log("牌堆中无装备");
        event2.finish();
        return;
      }
      if (equip1.name == "qinggang" && !lib.inpile.includes("qibaodao")) {
        equip1.remove();
        equip1 = game.createCard2("qibaodao", equip1.suit, equip1.number);
      }
      target2.$draw(equip1);
      await target2.chooseUseTarget(true, equip1, "nothrow", "nopopup");
      await game.delay();
      game.updateRoundNumber();
      const card2 = cards2[0];
      const bool1 = game.hasPlayer(function(current) {
        return current != player2 && target2.canUse(card2, current);
      });
      const bool2 = player2.canUse(card2, target2, false);
      let controlResult;
      if (bool1 && bool2) {
        controlResult = await target2.chooseControl(function() {
          return 0;
        }).set("choiceList", ["对除" + get.translation(player2) + "以外的角色使用" + get.translation(cards2) + "，并将装备区里的武器牌交给该牌的一个目标角色", "视为" + get.translation(player2) + "对你使用" + get.translation(cards2) + "，并将装备区内的武器牌交给" + get.translation(player2)]).forResult();
      } else if (bool1) {
        event2.directindex = 0;
      } else if (bool2) {
        event2.directindex = 1;
      } else {
        event2.finish();
        return;
      }
      if (controlResult && typeof event2.directindex != "number") {
        event2.directindex = controlResult.index;
      }
      if (event2.directindex == 1) {
        event2.insert(lib.skill.wylianji.content_use, {
          player: player2,
          target: target2,
          card: card2
        });
      } else {
        event2.insert(lib.skill.wylianji.content_give, {
          player: target2,
          card: card2,
          targets: game.filterPlayer(function(current) {
            return current != player2;
          })
        });
      }
    },
    async content_use(event2, trigger2, player2) {
      const { card: card2, target: target2 } = event2;
      await player2.useCard(card2, target2);
      if (!get.owner(card2)) {
        await target2.gain(card2, "gain2");
      }
      const equip1 = target2.getEquips(1);
      if (equip1.length) {
        await game.delay();
        await target2.give(equip1, player2);
        target2.line(player2);
      }
    },
    async content_give(event2, trigger2, player2) {
      const { card: card2, targets: targets2 } = event2;
      const select = get.select(get.info(card2).selectTarget);
      let result;
      if (select[1] == -1) {
        for (let i = 0; i < targets2.length; i++) {
          if (!player2.canUse(card2, targets2[i])) {
            targets2.splice(i--, 1);
          }
        }
        if (targets2.length) {
          await player2.useCard(card2, targets2);
        }
        event2.list = targets2.slice(0);
      } else {
        result = await player2.chooseTarget(select, "选择" + get.translation(card2) + "的目标", true, function(cardx, player3, target2) {
          var card3 = _status.event.card;
          return _status.event.targets.includes(target2) && player3.canUse(card3, target2);
        }).set("ai", function(target2) {
          var card3 = _status.event.card;
          var player3 = _status.event.player;
          return get.effect(target2, card3, player3, player3);
        }).set("targets", targets2).set("card", card2).forResult();
        if (result.bool) {
          await player2.useCard(card2, result.targets);
          event2.list = result.targets.slice(0);
        }
      }
      const equip1 = player2.getEquips(1);
      if (equip1.length) {
        for (let i = 0; i < event2.list.length; i++) {
          if (event2.list[i].isDead()) {
            event2.list.splice(i--, 1);
          }
        }
        if (event2.list.length > 1) {
          const result2 = await player2.chooseTarget(true, "将" + get.translation(equip1) + "交给一名角色", function(card3, player3, target2) {
            return _status.event.list.includes(target2);
          }).set("ai", function(target2) {
            return get.attitude(player2, target2);
          }).set("list", _status.event.list).forResult();
          event2.equip1 = equip1;
          if (result2.bool && result2.targets.length && event2.equip1) {
            await player2.give(event2.equip1, result2.targets[0]);
            player2.line(result2.targets);
          }
        } else {
          if (event2.list.length == 1) {
            await player2.give(equip1, event2.list[0]);
            player2.line(event2.list);
          }
          event2.finish();
          return;
        }
      } else {
        event2.finish();
        return;
      }
    },
    ai: {
      order: 7,
      result: {
        target(player2, target2) {
          if (ui.selected.cards.length) {
            var card2 = ui.selected.cards[0];
            var bool = card2.name != "sha";
            if (game.hasPlayer(function(current) {
              return target2.canUse(card2, current, bool) && get.effect(current, card2, target2, player2) > 0;
            })) {
              var num = 1;
              if (target2.getEquip(1)) {
                num = 0.6;
