{
    trigger: {
      player: "phaseUseEnd"
    },
    check(event, player) {
      var num = 0;
      var he = player.getCards("he");
      for (var i = 0; i < he.length; i++) {
        if (get.type(he[i], "trick") == "trick") {
          num++;
        }
        if (get.type(he[i]) == "equip") {
          var subtype = get.subtype(he[i]);
          if (subtype == "equip3" || subtype == "equip4" || subtype == "equip6") {
            num++;
          }
        }
      }
