                num -= Math.max(1, players[i].countCards("e"));
              } else if (att < 0) {
                num += Math.max(1, players[i].countCards("e"));
              }
            }
          }
          if (players.length < 5) {
            return num - 1;
          } else {
            return num - 2;
          }
        }
      }
    }
  }

