        case "basic":
        case "trick":
          await player.give(card, target, "give");
          break;
        case "delay":
          player.$give(card, target, false);
          await target.addJudge(card);
          break;
        case "equip":
          player.$give(card, target, false);
          await target.equip(card);
          break;
      }
      if (player === target) {
        return;
      }
