        case 2:
          if (nsha) {
            return Math.random() < 0.4;
          }
          return Math.random() < 0.2;
        case 3:
          if (nsha) {
            return Math.random() < 0.8;
          }
          return Math.random() < 0.3;
        case 4:
          if (nsha > 1) {
            return true;
          }
          if (nsha) {
            return Math.random() < 0.9;
          }
          return Math.random() < 0.5;
        default:
          return true;
      }
