sp:gushe.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filterTarget(card2, player2, target2) {
      return player2.canCompare(target2);
    },
    selectTarget: [1, 3],
    filter(event2, player2) {
      return player2.countCards("h") > 0;
    },
    multitarget: true,
    multiline: true,
    async content(event2, trigger2, player2) {
      const { targets: targets2 } = event2;
      const next = player2.chooseToCompare(targets2);
      next.callback = lib.skill.gushe.callback;
      await next;
    },
    intro: {
      name: "饶舌",
      content: "mark"
    },
    chat: ["粗鄙之语", "天地不容", "谄谀之臣", "皓首匹夫，苍髯老贼", "二臣贼子", "断脊之犬", "我从未见过有如此厚颜无耻之人！"],
    async callback(event2, trigger2, player2) {
      const { target: target2 } = event2;
      if (event2.winner !== player2) {
        target2.chat(lib.skill.gushe.chat[player2.countMark("gushe")]);
        await game.delay();
        player2.addMark("gushe", 1);
        if (player2.countMark("gushe") >= 7) {
          await player2.die();
        }
      }
      if (event2.winner !== player2) {
        const result = await player2.chooseToDiscard("he", "弃置一张牌，或摸一张牌").set("ai", function() {
          return -1;
        }).forResult();
        if (!result.bool) {
          await player2.draw();
        }
      }
      if (event2.winner !== target2) {
        const result2 = await target2.chooseToDiscard("he", "弃置一张牌，或令" + get.translation(player2) + "摸一张牌").set("ai", function(card2) {
          if (_status.event.goon) {
            return 6 - get.value(card2);
          }
          return 0;
        }).set("goon", get.attitude(target2, player2) < 0).forResult();
        if (!result2.bool) {
          await player2.draw();
        }
      }
    },
    ai: {
      order: 7,
      result: {
        target(player2, target2) {
          var num = ui.selected.targets.length + 1;
          if (num > 3) {
            num = 3;
          }
          var hs = player2.getCards("h");
          for (var i = 0; i < hs.length; i++) {
            if (get.value(hs[i]) <= 6) {
              switch (hs[i].number) {
                case 13:
                  return -1;
                case 12:
                  if (player2.countMark("gushe") + num <= 8) {
                    return -1;
                  }
                  break;
                case 11:
                  if (player2.countMark("gushe") + num <= 7) {
                    return -1;
                  }
                  break;
                default:
                  if (hs[i].number > 5 && player2.countMark("gushe") + num <= 6) {
                    return -1;
                  }
              }
            }
          }
          return 0;
        }
      }
    }
  }

